   "id": "3.3a",
   "type": "RULE",
   "force": "ADVISORY",
   "force_from": "imperative (\"Use\")",
   "text": "a driver SHOULD use low beams WHEN at night or in poor conditions AND the driver is less than 60 m behind another vehicle UNLESS the driver is passing the vehicle",
   "sources": [
    {
     "id": "m44",
     "quote": "Use your low beams when you are less than 60 metres behind another vehicle unless you are passing it."
    }
   ],
   "flags": [
    {
     "code": "M",
     "span": "less than 60 metres",
     "note": "A precise distance in a bare imperative reads like a legal duty, but the sentence has no legal wording, so it stays SHOULD."
    }
   ],
   "links": [],
   "note": "The sentence's main duty is a headlight rule, but its in-scope part is the passing exception, which sits in the same sentence and so is written as an UNLESS clause on the rule rather than a separate statement. The condition \"at night or in poor conditions\" comes from the heading \"Turn on headlights at night and in poor conditions\"."
  }
]}
